-- Payments (each one exactly as recorded: amount, date, method)
on conflict (id) do nothing;

-- Safety check: if anything differs from the Invoice Simple export, cancel everything.
do $$
declare v_n int; v_tot numeric; v_paid numeric; v_bal numeric; v_owing int; v_npay int;
begin
  select count(*), sum(total), sum(paid), sum(balance_due), count(*) filter (where balance_due > 0)
    into v_n, v_tot, v_paid, v_bal, v_owing
    from public.invoice_summary where is_imported;
  select count(*) into v_npay from public.payments where is_imported;
  if v_n <> 72 or v_tot <> 261995000 or v_paid <> 131110000 or v_bal <> 130885000 or v_owing <> 22 or v_npay <> 101 then
    raise exception 'Import check FAILED (invoices %, total %, paid %, owing %, invoices owing %, payments %). Nothing was saved.', v_n, v_tot, v_paid, v_bal, v_owing, v_npay;
  end if;
end $$;

commit;

-- Result: this should show 72 | 261,995,000 | 131,110,000 | 130,885,000 | 22 | 101
select count(*)                              as invoices_imported,
       sum(total)                             as total_invoiced,
       sum(paid)                              as total_paid,
       sum(balance_due)                       as total_outstanding,
       count(*) filter (where balance_due > 0) as invoices_with_balance,
       (select count(*) from public.payments where is_imported) as payments_imported
  from public.invoice_summary where is_imported;
